@startuml

class Location {
  + Address : string
}

class Driver {
  + FirstName : string
  + LastName : string
}

class Vehicle {
  + VehicleNumber : string
}

class Truck extends Vehicle {
  + Weight : float
}

class Car extends Vehicle {
  + Seats : int
}

class Van extends Vehicle {}

class Order {
  + Origin : string
  + Destination : string
  + Date : date
}

Location "1" -- "*" Driver
Location "1" -- "*" Vehicle
Location "1" -- "*" Order
Driver "1" -- "0..1" Order : carries out
Driver "1" -- "0..1" Vehicle : drives

